/* Bản dịch kịch bản «Giải mã tác phẩm» — Русский (ru). Claude dịch từ data/works.js, kiểm tra bằng i18n/validate.js (cập nhật 30/10/2026: 13 tác phẩm).
   {chữ hiện|cách đọc}: người xem thấy phần trước, giọng AI đọc phần sau (số, năm, thế kỷ, chữ khó đọc). */
window.ART_I18N = window.ART_I18N || {};
window.ART_I18N.ru = {"lang":"ru","v":2,"works":{"dong-ho-dam-cuoi-chuot":{"title":"Мышиная свадьба","artist":"Мастера деревни Донгхо (имена неизвестны)","date":"Традиционный сюжет (промысел гравюр Донгхо существует примерно с XVII века)","medium":"Гравюра на дереве, печать на бумаге до с перламутровым слоем из ракушек, природные краски","where":"Деревня гравюр Донгхо (Тхуантхань, провинция Бакнинь); оттиски хранятся во многих музеях","place":{"name":"Деревня гравюр Донгхо","prov":"Бакнинь"},"tags":["Донгхо","новогодняя гравюра","сатира","гравюра на дереве"],"hook":"На первый взгляд это просто весёлая мышиная свадьба — такие картинки вешают на Тет, Новый год по лунному календарю. Но присмотритесь: здесь открыто, средь бела дня, нарисована целая сцена подкупа.","intro":"«Мышиная свадьба», гравюра из деревни Донгхо, Бакнинь. Каждый цвет — своя доска, а печатают на бумаге до из коры дерева, покрытой блеском толчёных ракушек.","openers":["Это свадьба мышиного семейства — так почему же самый крупный персонаж на картине — кот?","Рядом с мышью, которая подносит коту птицу, есть маленькая деталь: два иероглифа, они читаются «тонг ле».","Найдите двух мышей, которые дуют в трубы. Эту музыку можно понять двумя прямо противоположными способами."],"trendLine":"Теперь я понимаю, почему на одну народную гравюру можно смотреть часами…","end":"Картинка с мышами, чтобы посмеяться на Тет, — а рассказывает она о власти и подношениях целого общества. Теперь вы понимаете, почему на «Мышиную свадьбу» можно смотреть часами.","img":[{"by":"Мастера Донгхо · фото: Wikimedia Commons","lic":"Общественное достояние"}],"steps":[{"tag":"🐱 Кот = власть имущий","q":"Вы заметили, кто на картине самый большой?","a":"Не невеста и не жених, а кот. Он занимает весь верхний угол и поднял лапу, будто отдаёт приказ. По словам мастеров Донгхо, кот — это власть имущий, а мышиное семейство — простой народ.","s":"Не невеста, а кот. По словам мастеров, кот — власть имущий, а мыши — простой народ."},{"tag":"🐦 «Тонг ле» = подношение","q":"Что подносит коту мышь, идущая впереди?","a":"Птицу. А прямо под ней два иероглифа, они читаются «тонг ле» — «вручить подношение». Чтобы свадьба прошла спокойно, мышиному семейству сначала нужно подмазать кота.","s":"Птицу, а рядом иероглифы «тонг ле» — «вручить подношение». Чтобы свадьба прошла спокойно, сначала надо подмазать кота."},{"tag":"🐟 Рыба и птица","q":"А что держит вторая мышь?","a":"Карпа. И птица, и рыба — любимые лакомства кота. Посмотрите, как подобострастно согнулись мыши с подарками: так стоят те, кто боится."},{"tag":"🎺 «Так няк» = музыка","q":"Две мыши с трубами празднуют свадьбу — или заняты чем-то другим?","a":"Рядом два иероглифа «так няк» — «играть музыку». Одни считают, что трубы играют, чтобы порадовать кота, пока он принимает подарки. Есть и обратное прочтение: трубы гремят как раз для того, чтобы вся деревня узнала о взятке."},{"tag":"📜 Четыре иероглифа","q":"Что говорят четыре иероглифа в левом верхнем углу?","a":"В прессе их обычно читают как «Лао тхы тху тхан», но единого мнения о чтении и смысле этой строки до сих пор нет. Сюжет мышиной свадьбы есть и в китайских новогодних картинах, где в одной из версий кот в конце концов съедает невесту. А в Донгхо мастера оставили сцену с подношениями и превратили её в сатиру."},{"tag":"🐴 Жених на коне","q":"А где же жених?","a":"По словам мастера Нгуен Хыу Шама, вот он: на розовом коне, в шапке, одет как мандарин, а позади слуга держит над ним парадный зонт. В некоторых источниках иероглифы рядом читают как «тю хон» — распорядитель свадьбы. Кто бы это ни был, мышиная свадьба устроена точь-в-точь как свадьба знатных людей.","s":"На розовом коне, в шапке, одет как мандарин (есть прочтение, что это распорядитель свадьбы): мышиная свадьба — точь-в-точь свадьба знати."},{"tag":"👰 Паланкин невесты","q":"А где сидит невеста?","a":"В паланкине с жёлтой крышей, который несут четыре мыши. Есть и парадная табличка, и зонт, и музыка — всё по свадебному обряду. Именно эта торжественность делает сцену со взяткой наверху ещё ироничнее.","s":"В паланкине с жёлтой крышей, который несут четыре мыши, — торжественно, по всем правилам свадебной процессии."},{"tag":"〰️ Рассказ в два яруса","q":"Зачем картину делит пополам волнистая линия?","a":"В народной картине нет западной линейной перспективы. Эта линия разделяет две сцены: сверху — процессия с подношениями коту, снизу — свадебный кортеж. Две истории идут одна за другой, как два кадра комикса."},{"tag":"❔ Пять чёрных точек","q":"А что за пять маленьких чёрных точек слева?","a":"Честный ответ: никто точно не знает. Такие точки на картинах с мышами мастер Нгуен Хыу Шам толкует как пять стихий — пожелание мышиному роду плодиться и жить в согласии. Это лишь одно из толкований, а не единственная разгадка."},{"tag":"🎨 Краски из природы","q":"Откуда взялись эти краски?","a":"Все из природы: красная — из охристой гальки, жёлтая — из цветков софоры, синяя — из листьев индиго, чёрная — из золы бамбуковых листьев или рисовой соломы. Блестящий фон — порошок из ракушек на клейстере из клейкого риса. Для каждого цвета своя доска, а чёрный контур печатают последним.","s":"Красная — из охристой гальки, жёлтая — из цветков софоры, синяя — из индиго, чёрная — из золы бамбуковых листьев. Блестящий фон — толчёные ракушки."}]},"dong-ho-lon-nai":{"title":"Свиньи инь-ян","artist":"Мастера деревни Донгхо (имена неизвестны)","date":"Традиционный сюжет","medium":"Гравюра на дереве, печать на бумаге до с перламутровым слоем из ракушек, природные краски","where":"Деревня гравюр Донгхо (Тхуантхань, провинция Бакнинь)","place":{"name":"Деревня гравюр Донгхо","prov":"Бакнинь"},"tags":["Донгхо","благопожелательная картина","инь и ян"],"hook":"Круглая упитанная свинья с поросятами — такую картинку вешают на Тет, лунный Новый год. Но посмотрите на завиток у неё на боку: это целая вселенная в миниатюре.","intro":"«Свиньи инь-ян», гравюра на дереве из деревни Донгхо. На картине нет ни одного слова — пожелание высказывает сам рисунок.","openers":["Почему на многих гравюрах Донгхо у свиньи ровно пять поросят, и все разного цвета?","Одна деталь на боку этой свиньи родилась из опыта старых крестьян, которые отбирали скот на племя.","Остановитесь и посмотрите на пятачок свиньи-матери: он повёрнут в профиль или смотрит прямо на вас?"],"trendLine":"Теперь я понимаю, почему на одну новогоднюю гравюру можно смотреть часами…","end":"Ни одного слова — только завиток и семейство круглых упитанных свиней, а в них предки вложили и философию инь и ян, и мечту о сытой жизни. Теперь вы понимаете, почему на эту картину можно смотреть часами.","img":[{"by":"Мастера Донгхо · фото: Wikimedia Commons","lic":"Общественное достояние"}],"steps":[{"tag":"☯️ Вихор = инь-ян","q":"Что это за завиток на спине свиньи-матери?","a":"Это символ инь и ян. А происхождение у него очень житейское: вихор щетины на теле свиньи. Старые крестьяне считали такой вихор признаком хорошей породы, и мастер превратил его в знак инь-ян — пожелание плодиться без конца.","s":"Символ инь и ян, выросший из вихра щетины — признака хорошей породы: пожелание плодиться без конца."},{"tag":"🐷 Порода «и»","q":"Что это за порода, раз свинья такая круглая?","a":"Это свинья породы «и» — старинной породы Северного Вьетнама, с провисшей спиной и большим брюхом. Настоящие свиньи в старину были куда худее. Картина рисует не то, что есть, а то, о чём мечтает крестьянин: сытый, полный до краёв год.","s":"Порода «и», старинная порода Северного Вьетнама. Картина рисует не то, что есть, а то, о чём мечтают: сытый год."},{"tag":"👃 И в профиль, и анфас","q":"Пятачок этой свиньи — в профиль или анфас?","a":"И то и другое. Автор Фунг Хонг Кон обратил внимание, что пятачок нарисован одновременно и сбоку, и спереди. Народному мастеру не нужны законы перспективы: он рисует так, чтобы всё было видно как можно лучше."},{"tag":"5️⃣ Пятеро, пять цветов","q":"Сколько поросят у свиньи-матери?","a":"На этом оттиске пять поросят, и каждый своего цвета. Мастер Нгуен Хыу Куа говорит, что пять — ровно по числу пяти стихий. Так картину читают в деревне; число поросят на разных досках бывает разным.","s":"Пятеро, каждый своего цвета. Мастера Донгхо видят в этом ровно пять стихий."},{"tag":"🐖 Полон дом детей","q":"Что делает поросёнок справа?","a":"Забрался на маму и задрал голову, будто смеётся. У каждого своя поза: один карабкается, другой прижимается к матери, третий увлечённо ест. Это образ большой семьи, где детей и внуков не счесть, — шумного и весёлого дома, о котором в старину мечтали к каждому Новому году."},{"tag":"☯️ От матери к детям","q":"Вы заметили, что у поросят тоже есть завитки?","a":"Именно так. Доски заново вырезали многие поколения мастеров, детали могли меняться, но знак инь-ян сохраняли всегда — как пожелание, которое мать передаёт детям."},{"tag":"🌙 Объём пятнами цвета","q":"Зачем на теле свиньи эти пятна в форме полумесяца?","a":"Так мастер создаёт объём. Ни теней, ни светотени — всего несколько изогнутых цветных пятен, и тело свиньи уже круглое и упругое."},{"tag":"🌱 Корм","q":"А что за кустик у ног свиней?","a":"Наверное, это корм: один поросёнок жуёт листья. Для крестьянина сытое свиное семейство — это и есть пожелание богатого года."},{"tag":"✨ Перламутровый слой","q":"Почему фон картины так переливается?","a":"Это слой «дьеп»: мелко истолчённые ракушки на клейстере из клейкого риса, которыми покрывают бумагу до из коры дерева. В свете лампы свиньи будто вспыхивают. Поэт Хоанг Кам упоминал картинки с петухами и свиньями на такой бумаге в стихотворении «На том берегу реки Дуонг».","s":"Это слой «дьеп»: толчёные ракушки на рисовом клейстере, нанесённые на бумагу до, — и свиньи будто светятся."}]},"dong-ho-ga":{"title":"Петух Донгхо","artist":"Мастера деревни Донгхо (имена неизвестны)","date":"Традиционный сюжет (обычай вешать картинки с петухом известен с XVI века)","medium":"Гравюра на дереве, печать на бумаге до, природные краски","where":"Музей изобразительных искусств Вьетнама, Ханой (вариант с петухом и курицей на фото)","place":{"name":"Музей изобразительных искусств Вьетнама","prov":"Ханой"},"tags":["Донгхо","новогодняя гравюра","пять добродетелей"],"hook":"На Тет, Новый год по лунному календарю, в старину на двери клеили картинки с петухом. Но этот петух не просто для красоты: в нём пять добродетелей, которым предки хотели научить детей и внуков.","intro":"Петух Донгхо — гравюра на дереве, отпечатанная на бумаге до из коры дерева. Оттиск, который вы видите, — с петухом, курицей и цыплятами — хранится в Музее изобразительных искусств Вьетнама.","openers":["С чьей шапкой в старину сравнивали красный гребень этого петуха?","Одну добродетель петуха на картине не увидеть, как ни вглядывайся.","Найдите шпору на ноге петуха. Для предков она означала целую добродетель."],"trendLine":"Теперь я понимаю, почему на одного нарисованного петуха можно смотреть часами…","end":"Учёность, доблесть, храбрость, человеколюбие и верность — пять добродетелей в одном петухе на бумаге до. Теперь вы понимаете, почему с приходом весны такую картинку вешали прямо на дверь дома.","img":[{"by":"Фото: Daderot (CC0) · Музей изобразительных искусств Вьетнама","lic":"CC0"},{"by":"Мастера Донгхо · фото: Wikimedia Commons","lic":"Общественное достояние"}],"steps":[{"tag":"🎓 Гребень = учёность","q":"На что похож красный гребень петуха?","a":"В старину его сравнивали с шапкой учёного-книжника. Поэтому гребень символизирует учёность — первую из пяти добродетелей петуха."},{"tag":"⚔️ Шпоры = доблесть","q":"Какую добродетель прячут эти ноги?","a":"На ногах петуха шпоры — оружие для боя. Шпоры символизируют воинскую доблесть."},{"tag":"🦁 Грудь вперёд = храбрость","q":"А эта поза с гордо выпяченной грудью?","a":"Это храбрость: встретив противника, петух бросается в бой и не отступает."},{"tag":"⏰ Поёт в срок = верность","q":"Что говорят иероглифы на этой картине?","a":"«За сыонг нгу кань хоа»: ночью петух поёт, исправно отмечая все пять ночных страж. В старину часов не было, и петушиный крик отмечал каждую стражу. Петь точно в срок — это верность."},{"tag":"❤️ Зов = человеколюбие","q":"А пятую добродетель вы не увидите. Какая же она?","a":"Это человеколюбие: найдя корм, петух созывает всех, чтобы поесть вместе. Сам зов картина нарисовать не может, но показывает, к чему он привёл: курица и цыплята дружно собрались рядом."},{"tag":"🐣 Цыплята","q":"Видите цыплёнка, который забирается маме на спину?","a":"У каждого цыплёнка своя поза: один лезет на спину матери, другой выхватывает корм, третий хлопает крылышками. Картинка с выводком — пожелание большой и дружной семьи."},{"tag":"🦵 «Золотой петух»","q":"Почему этот петух стоит на одной ноге?","a":"Это поза «ким ке док лап» — «золотой петух стоит на одной ноге»: устойчивая и гордая стойка петуха в ту минуту, когда он поёт."},{"tag":"🖨️ Каждый цвет — своя доска","q":"Как напечатан этот яркий хвост?","a":"Для каждого цвета своя доска, оттиски ложатся друг на друга, а чёрный контур печатают последним — он словно собирает цветные пятна воедино."},{"tag":"🚪 Страж двери на Тет","q":"С каких пор вьетнамцы вешают петуха на Тет?","a":"Примерно с {XVI–XVII веков|шестнадцатого-семнадцатого веков}: в стихотворении Хоанг Ши Кхая описано, как в столице Тханглонг на Тет вешали картинки с петухом, чтобы отогнать злых духов. Крик петуха зовёт солнце и прогоняет тьму — как раз то, чего ждут от нового года.","s":"Примерно с {XVI–XVII веков|шестнадцатого-семнадцатого веков}: крик петуха зовёт солнце и прогоняет тьму — то, чего ждут от нового года."}]},"hang-trong-ngu-ho":{"title":"Пять тигров","artist":"Мастера улицы Хангчонг, Ханой (имена неизвестны)","date":"Традиционный сюжет (расцвет — конец XIX – начало XX века)","medium":"Полупечать-полуроспись: контур — оттиск с доски, цвет — от руки, бумага до","where":"Музей изобразительных искусств Вьетнама, Ханой (экземпляр на фото)","place":{"name":"Улица Хангчонг, район Хоанкьем","prov":"Ханой"},"tags":["Хангчонг","культовая картина","пять стихий"],"hook":"Пять тигров, пять цветов, среди облаков и скал. Но если пройти по картине по часовой стрелке, она расскажет вам о целом круговороте неба и земли.","intro":"«Пять тигров» — картина с ханойской улицы Хангчонг. С доски печатают только контур, а цвет наносят от руки, слой за слоем, поэтому двух одинаковых картин не бывает.","openers":["Почему в храмах Богини-Матери пять тигров сидят на самом нижнем алтаре и им подносят сырое мясо?","У лап жёлтого тигра есть маленькая деталь — командная табличка, и надпись на ней не на всех экземплярах одинакова.","Остановитесь и посмотрите по сторонам от тигров: с одной стороны меч, с другой — командный флаг, как у настоящего войска."],"trendLine":"Теперь я понимаю, почему на одну картину с тиграми можно смотреть часами…","end":"Пять тигров, пять цветов, пять сторон света — и все они сложились в бесконечный круг рождения. Теперь вы понимаете, почему перед «Пятью тиграми» можно стоять часами.","img":[{"by":"Фото: Daderot · Музей изобразительных искусств Вьетнама","lic":"Общественное достояние"}],"steps":[{"tag":"🟡 Жёлтый тигр = Земля","q":"Почему жёлтый тигр в центре намного больше остальных?","a":"Это Жёлтый тигр, он соответствует стихии Земля и стоит в центре, где сходятся четыре другие стихии. В храмах жёлтый тигр — командир всей стаи."},{"tag":"⚪ Белый тигр = Металл","q":"Кто этот белый тигр на облаке в верхнем углу?","a":"Белый тигр: стихия Металл, запад, осень. Два тигра наверху, на облаках, принадлежат небу, а два внизу, на скалах, — земле."},{"tag":"⚫ Чёрный тигр = Вода","q":"А чёрный тигр справа?","a":"Чёрный тигр: стихия Вода, север, зима."},{"tag":"🔴 Красный тигр = Огонь","q":"Кто этот рычащий красный тигр в нижнем углу?","a":"Красный тигр: стихия Огонь, юг, лето. Оставшийся справа по канону — Зелёный тигр: стихия Дерево, восток, весна. Цвет наносят от руки, поэтому на каждом экземпляре оттенки свои."},{"tag":"🔄 Круг порождения","q":"Теперь пройдите по часовой стрелке, начиная с зелёного тигра. Что вы видите?","a":"При этой распространённой раскладке цветов: зелёный, потом красный, потом жёлтый в центре, потом белый, потом чёрный. Это и есть круг взаимопорождения пяти стихий: Дерево рождает Огонь, Огонь — Землю, Земля — Металл, Металл — Воду, а Вода снова рождает Дерево. Пять тигров — круговорот, который никогда не прерывается.","s":"Зелёный, красный, жёлтый, белый, чёрный — круг взаимопорождения стихий: Дерево рождает Огонь, Огонь — Землю, Земля — Металл, Металл — Воду."},{"tag":"✨ Созвездие","q":"Что это за соединённые точки над головой жёлтого тигра?","a":"Созвездие; есть мнение, что это Большая Медведица. Небо, звёзды и пять сторон света уместились в одной картине: «Пять тигров» — словно маленькая карта вселенной."},{"tag":"🗡️ Стражи пяти лагерей","q":"Почему у тигров есть и меч, и командный флаг?","a":"Потому что это небесное войско. В храмах Богини-Матери пятерых тигров зовут «куан нгу зинь» — военачальники пяти лагерей. Меч — это власть, флаг — приказ."},{"tag":"📜 Командная табличка","q":"Что за маленькая табличка у лап жёлтого тигра?","a":"Это командная табличка — знак божественной власти. Надпись на ней на каждом экземпляре своя, на некоторых — иероглиф «выонг», то есть «царь»."},{"tag":"🏮 Нижний алтарь храма","q":"Где почитают эту картину?","a":"В храмах и святилищах Богини-Матери пять тигров сидят на самом нижнем алтаре, прямо под главным, и охраняют вход. Тиграм обычно подносят сырое мясо и сырые яйца. А на Тет, лунный Новый год, многие семьи вешают картину с тиграми, чтобы в доме было спокойно.","s":"На самом нижнем алтаре в храме Богини-Матери, на страже у входа; им обычно подносят сырое мясо и сырые яйца."},{"tag":"🖌️ Печать и роспись","q":"Присмотритесь к шерсти тигра. Что вы видите?","a":"Слои краски, растушёванные вручную: где-то гуще, где-то светлее. В этом главное отличие Хангчонга от Донгхо: в Донгхо цвет печатают ровными пятнами с досок, а в Хангчонге печатают только контур и раскрашивают от руки."}]},"to-ngoc-van-thieu-nu-ben-hoa-hue":{"title":"Девушка с лилиями","artist":"То Нгок Ван (1906–1954)","date":"1943","medium":"Масло","where":"Местонахождение оригинала не установлено (Музей изобразительных искусств Вьетнама продолжает поиски, декабрь 2025)","place":{"name":"Музей изобразительных искусств Вьетнама (здесь хранится картина-«близнец» «Девушка с лотосами»)","prov":"Ханой"},"tags":["искусство Индокитая","масляная живопись","аозай"],"hook":"Это, пожалуй, самая известная вьетнамская картина. Но есть факт, о котором мало кто знает: очень многие репродукции, что ходят по рукам, сделаны с копий, а оригинал музей до сих пор ищет.","intro":"«Девушка с лилиями» — То Нгок Ван написал её маслом в {1943 году|тысяча девятьсот сорок третьем году}.","openers":["Знаете ли вы, кто эта девушка в белом рядом с вазой цветов?","Одна деталь скрыта прямо в названии: цветы на картине — вовсе не те, что во Вьетнаме обычно зовут этим словом.","Попробуйте сосчитать, сколько разных оттенков белого на этой картине."],"trendLine":"Теперь я понимаю, почему на одну картину можно смотреть часами…","end":"Тихое мгновение, несколько лилий и очень много оттенков белого. Теперь вы понимаете, почему «Девушкой с лилиями» можно любоваться всю жизнь — и не наскучит.","img":[{"by":"То Нгок Ван · репродукция из Wikimedia Commons","lic":"Общественное достояние"}],"steps":[{"tag":"👁️ Мечтательный взгляд","q":"Вы обратили внимание на взгляд девушки?","a":"Она не смотрит на нас. Глаза полуприкрыты, голова склонена к вазе с цветами, будто она задумалась о чём-то очень личном. Именно это тихое мгновение не даёт зрителю отвести глаз."},{"tag":"🌸 «Западный хюэ» = лилия","q":"Что же это за цветы на самом деле?","a":"Во вьетнамском названии цветок назван «хюэ», но здесь это «западный хюэ», то есть белоснежная лилия, которая в Ханое цветёт в конце марта — начале апреля. С обычным хюэ — туберозой, которую ставят на алтарь, когда возжигают благовония, — у неё нет ничего общего. Лилия — символ чистоты.","s":"Это «западный хюэ», то есть апрельская ханойская лилия, а не тубероза для алтаря. Она символ чистоты."},{"tag":"✋ Замкнутая дуга","q":"Одна рука поднята к волосам. Зачем?","a":"Этот жест замыкает композицию: рука, голова и цветы образуют дугу, которая обнимает лицо. Взгляд зрителя скользит по кругу и останавливается на лице."},{"tag":"🤍 Лёгкое касание","q":"А другая рука?","a":"Она едва касается лепестков — не держит, не срывает. Очень лёгкий жест, словно девушка боится сделать цветку больно."},{"tag":"🤍 Белое на белом","q":"Сколько оттенков белого вы насчитали на картине?","a":"Белый аозай, белые цветы, светлая ваза — но ни один белый не повторяет другой. Художник смешивал белила с кремово-жёлтым, голубым, розовым и получил множество оттенков. Писать белое по белому так, чтобы всё оставалось различимым, — вот задача, достойная мастера, и в этом главная трудность картины."},{"tag":"🏺 Синий акцент","q":"Какую роль играет бело-синяя ваза?","a":"В общей жёлто-белой гамме синий узор на вазе — редкий акцент, и он притягивает взгляд к цветам."},{"tag":"🧑‍🎨 Натурщица по имени Шау","q":"Кто эта девушка на картине?","a":"По словам сына художника, это профессиональная натурщица по имени Шау, которую То Нгок Ван нанимал с {1939 года|тысяча девятьсот тридцать девятого года}. Позже она позировала и Нгуен Зя Чи, и Чан Ван Кану. Когда сын художника стал её разыскивать, её уже не было в живых.","s":"По словам сына художника, это Шау — профессиональная натурщица, которую он нанимал с {1939 года|тысяча девятьсот тридцать девятого года}."},{"tag":"🔎 Где оригинал?","q":"Почему одна из самых знаменитых картин не признана национальным сокровищем?","a":"По словам одного эксперта, потому что до сих пор не установлено, какой экземпляр подлинный. Картина прошла через руки многих коллекционеров, в музее когда-то висела копия, а в одной книге {1983 года|тысяча девятьсот восемьдесят третьего года} по ошибке даже напечатали подделку. В {декабре 2025 года|декабре две тысячи двадцать пятого года} Музей изобразительных искусств Вьетнама сообщил, что всё ещё ищет оригинал.","s":"По словам эксперта, подлинник так и не установлен: картина сменила многих владельцев, есть и копии, и подделки. Музей всё ещё её ищет."},{"tag":"👯 Картина-близнец","q":"У этой картины есть сестра-близнец?","a":"Да: «Девушка с лотосами», с той же натурщицей, её хранит Музей изобразительных искусств Вьетнама. После реставрации она впервые предстала перед публикой в {декабре 2025 года|декабре две тысячи двадцать пятого года}."}]},"to-ngoc-van-hai-thieu-nu-va-em-be":{"title":"Две девушки и ребёнок","artist":"То Нгок Ван (1906–1954)","date":"1944","medium":"Холст, масло","where":"Музей изобразительных искусств Вьетнама, ул. Нгуен Тхай Хок, 66, Ханой","place":{"name":"Музей изобразительных искусств Вьетнама","prov":"Ханой"},"tags":["искусство Индокитая","масляная живопись","национальное сокровище"],"hook":"Две девушки беседуют на веранде, мальчик играет на полу. Самая обычная сцена. Но мальчик в красном — это сын самого художника.","intro":"«Две девушки и ребёнок», масло, То Нгок Ван, {1944 год|тысяча девятьсот сорок четвёртый год}. Национальное сокровище, сейчас в Музее изобразительных искусств Вьетнама.","openers":["Знаете ли вы, что, по словам семьи художника, у этой картины было другое название, связанное с цветком?","Один цвет повторяется на этой картине несколько раз, и, похоже, это не случайно.","Попробуйте понять, в какую фигуру выстроились три персонажа этой картины."],"trendLine":"Теперь я понимаю, почему на одну тихую семейную сцену можно смотреть часами…","end":"Мирный семейный вечер, сохранённый в тёплой жёлтой гамме и в цветке, который утром распускается, а к вечеру вянет. Теперь вы понимаете, почему на эту картину можно смотреть часами.","img":[{"by":"То Нгок Ван · фото: Wikimedia Commons","lic":"Общественное достояние"}],"steps":[{"tag":"👦 Сын художника","q":"Кто этот мальчик в красном в углу картины?","a":"По словам самого То Нгок Тханя, сына художника, это он в четыре года. Картину писали прямо дома, в семейном доме на улице Кхамтхьен."},{"tag":"👩 Учительница Май","q":"А девушка в жёлтом, что сидит на бамбуковом топчане?","a":"По словам того же То Нгок Тханя, позировала учительница Май, подруга жены художника. А девушка в белом, сидящая на полу, — племянница художника."},{"tag":"🔺 Композиция-треугольник","q":"Видите, в какую фигуру выстроились три персонажа?","a":"В треугольник: вершина — девушка в жёлтом, углы основания — девушка в белом и мальчик. Треугольная композиция классической западной живописи создаёт ощущение покоя и равновесия посреди очень вьетнамской обстановки."},{"tag":"🌺 Гибискус","q":"Что за цветы на кусте позади?","a":"По словам семьи художника, это гибискус — цветок, который утром распускается, а к вечеру вянет. То Нгок Ван сравнивал с ним судьбу девушки, и первое название картины было «Девушка и гибискус».","s":"По словам семьи художника, это гибискус: утром расцветает, к вечеру вянет; первое название картины — «Девушка и гибискус»."},{"tag":"🌸 Три розовых акцента","q":"Вы заметили, сколько раз повторяется розовый цвет?","a":"Цветок в руке девушки в жёлтом, заколка в волосах девушки в белом и цветы позади. Три розовых пятна будто напоминают о цветке из первого названия картины. Это лишь одно из прочтений — проверьте сами."},{"tag":"🤍 Девушка в белом","q":"Что делает девушка в белом?","a":"Сидит на полу, подняв голову, и слушает. Полы белого аозая раскинулись по плиточному полу и контрастируют с тёплым жёлтым нарядом девушки, сидящей выше."},{"tag":"☀️ Тёплая жёлтая гамма","q":"Почему вся картина будто залита солнцем?","a":"Тёплая жёлтая гамма ложится на всё: одежду, бамбуковый топчан, пол, стену. Согласно досье национального сокровища, этот жёлтый связывает человека и природу в единое гармоничное целое."},{"tag":"🎋 Ханойская веранда","q":"О чём говорит бамбуковая штора над головой?","a":"Бамбуковая штора, бамбуковый топчан, веранда — очень вьетнамские вещи вписаны в композицию, заимствованную у классической западной живописи."},{"tag":"💰 200 донгов (1965)","q":"За сколько когда-то уступили национальное сокровище?","a":"Около {1965 года|тысяча девятьсот шестьдесят пятого года} владелец картины, врач Нгуен Тан Зи Чонг, друг художника, уступил её музею за {200 донгов|двести донгов}. А в {1970 году|тысяча девятьсот семидесятом году} То Нгок Тхань с удивлением увидел в Праге репродукции этой картины — их продавали как сувениры.","s":"Около {1965 года|тысяча девятьсот шестьдесят пятого года} картину уступили музею за {200 донгов|двести донгов}, а в {1970 году|тысяча девятьсот семидесятом году} её репродукции продавали в Праге как сувениры."}]},"nguyen-phan-chanh-choi-o-an-quan":{"title":"Игра в о ан куан","artist":"Нгуен Фан Тянь (1892–1984)","date":"1931","medium":"Живопись на шёлке","where":"Музей азиатского искусства Фукуоки, Япония","place":{"name":"Музей азиатского искусства Фукуоки","prov":"За рубежом · Япония"},"tags":["живопись на шёлке","искусство Индокитая","народные игры"],"hook":"Четыре девочки сидят прямо на земле и играют в игру, привычную во Вьетнаме. Но обратите внимание: почти все взгляды на картине прикованы к одной руке.","intro":"«Игра в о ан куан», живопись на шёлке, Нгуен Фан Тянь, {1931 год|тысяча девятьсот тридцать первый год}.","openers":["Угадайте, в какой стране сейчас хранится эта картина на шёлке?","Одну деталь этой картины французский чиновник когда-то раскритиковал: мол, не во вкусе покупателей.","Найдите на этой картине игровую доску. Подсказка: не ищите её на столе."],"trendLine":"Теперь я понимаю, почему на одну картину на шёлке можно смотреть часами…","end":"Детская игра, деревенская коричневая гамма и одна рука в центре. Теперь вы понимаете, почему «Игру в о ан куан» считают вехой вьетнамской живописи на шёлке.","img":[{"by":"Фото: Музей азиатского искусства Фукуоки","lic":"© Нгуен Фан Тянь"}],"steps":[{"tag":"✋ Центр картины","q":"Вы заметили руку, которая делает ход?","a":"Все взгляды направлены на неё. Художник рассказывал, что нарочно дал первый ход самой младшей девочке, чтобы внимание всей группы сошлось в одной точке. Эта рука — центр всей картины."},{"tag":"⚖️ Трое против одной","q":"Почему девочки сидят трое против одной?","a":"Художник рассказывал, что посадил одну девочку с одной стороны, а трёх — тесной группой с другой, чтобы композиция не распадалась, а светлые и тёмные пятна уравновешивали друг друга."},{"tag":"🪨 Доска на земле","q":"Где же игровая доска?","a":"Она начерчена прямо на земле: в маленьких клетках лежат фишки-камешки, а две крайние клетки — это клетки «мандаринов». В старину в о ан куан играли девочки примерно от семи до десяти лет."},{"tag":"🧣 Зимний день","q":"Что платок на голове девочки говорит о времени года?","a":"Это платок «вороний клюв», какие носили женщины Северного Вьетнама. В дневнике художника описано, как дети тепло одевались в холодные дни в деревне Кимльен. На картине — зимний день."},{"tag":"🟤 Приглушённый коричневый","q":"Почему вся картина в приглушённой коричневой гамме?","a":"Это цвет коричневой крестьянской одежды, оживлённый капелькой чёрного, жёлтого и красного. В {1932 году|тысяча девятьсот тридцать втором году}, когда картину продавали в Париже, один французский чиновник даже упрекнул её в слишком тусклых красках, не во вкусе французских покупателей. А со временем эта приглушённая гамма стала фирменным почерком шёлковой живописи Нгуен Фан Тяня."},{"tag":"💧 Писать и смывать","q":"Как шёлк стал таким мягким, словно туман?","a":"Нгуен Фан Тянь наносил слой краски, давал ему высохнуть, промывал картину в воде, потом снова писал и снова промывал — много раз. Краска так пропитывала шёлк, что обе стороны ткани выглядели почти одинаково."},{"tag":"✍️ Стихи и печать","q":"Что это за строки иероглифов в углу картины?","a":"На его картинах на шёлке обычно есть стихотворение, написанное иероглифами, красная печать и подпись. Стихи не обязательно пересказывают то, что изображено на картине."},{"tag":"🗾 Фукуока, Япония","q":"Где сейчас эта картина?","a":"В Японии, в Музее азиатского искусства Фукуоки. В {1932 году|тысяча девятьсот тридцать втором году} её продали в Париже за две тысячи франков, и известный французский журнал напечатал её в цвете. На тот же сюжет художник написал ещё несколько вариантов."}]},"tran-van-can-em-thuy":{"title":"Маленькая Тхюи","artist":"Чан Ван Кан (1910–1994)","date":"1943","medium":"Холст, масло","where":"Музей изобразительных искусств Вьетнама, ул. Нгуен Тхай Хок, 66, Ханой","place":{"name":"Музей изобразительных искусств Вьетнама","prov":"Ханой"},"tags":["портрет","масляная живопись","национальное сокровище"],"hook":"Восьмилетняя девочка сидит в плетёном кресле, сцепив руки. Кое-кто называет эту картину вьетнамской Моной Лизой. Почему?","intro":"«Маленькая Тхюи», масло, Чан Ван Кан, {1943 год|тысяча девятьсот сорок третий год}. Национальное сокровище, Музей изобразительных искусств Вьетнама.","openers":["Знаете ли вы, что девочка с этой картины — реальный человек и прожила до {2024 года|две тысячи двадцать четвёртого года}?","Одна деталь этой картины когда-то пострадала сильнее всего, и, возможно, вы смотрите прямо на неё.","Присмотритесь к платью девочки: оно правда белое?"],"trendLine":"Теперь я понимаю, почему на один детский портрет можно смотреть часами…","end":"Девочка, розовое шёлковое платье и взгляд, прошедший сквозь восемьдесят с лишним лет. Теперь вы понимаете, почему «Маленькую Тхюи» называют вьетнамской Моной Лизой.","img":[{"by":"Фото: Музей изобразительных искусств Вьетнама","lic":"© Чан Ван Кан"}],"steps":[{"tag":"👁️ Взгляд","q":"На кого смотрят эти блестящие чёрные глаза?","a":"Прямо на нас — круглые, чёрные и блестящие. Реставратор Кэролайн Фрай назвала картину вьетнамской Моной Лизой, а английскому композитору Полу Зеттеру казалось, что девочка следит взглядом за зрителем."},{"tag":"👧 Нгуен Минь Тхюи","q":"Кто такая Тхюи?","a":"Это Нгуен Минь Тхюи, она родилась в {1935 году|тысяча девятьсот тридцать пятом году} и звала художника дядей. В восемь лет она много раз позировала ему на улице Хангкот. Выросла, стала учительницей и умерла в {2024 году|две тысячи двадцать четвёртом году}, прожив восемьдесят девять лет."},{"tag":"🎀 Бледно-розовый шёлк","q":"Платье кажется белым, но какого оно цвета на самом деле?","a":"Это бледно-розовое платье из хадонгского шёлка. Именно когда художник увидел девочку в этом платье, ему захотелось её написать."},{"tag":"🤲 Робость","q":"О чём говорят сцепленные руки?","a":"О лёгкой робости восьмилетнего ребёнка, которому велели сидеть смирно перед мольбертом. Корпус чуть подался вперёд, руки послушно сложены на коленях."},{"tag":"🪑 Плетёное кресло","q":"Какую роль играет плетёное кресло?","a":"Коричневое плетёное кресло обнимает светлое платье и выделяет лицо. Крупные цветовые пятна, свободный мазок — реставратор Кэролайн Фрай хвалила именно эту манеру за восточный дух."},{"tag":"🩹 Спасение картины","q":"Какая часть картины пострадала сильнее всего?","a":"Само лицо. К {2003 году|две тысячи третьему году} картина была покрыта пылью и копотью, засижена насекомыми, красочный слой вздулся и осыпался. Реставратор Кэролайн Фрай из Австралии много месяцев работала в музее и вернула картину {28 июня 2004 года|двадцать восьмого июня две тысячи четвёртого года}."},{"tag":"🔎 Пропажа","q":"Как картина потерялась?","a":"В {1943 году|тысяча девятьсот сорок третьем году} картина получила первую премию на выставке в Ханое, а потом затерялась во время войны. По одним рассказам, музей выкупил её в {1964 году|тысяча девятьсот шестьдесят четвёртом году} за {300 донгов|триста донгов}, по другим — её нашли в доме одного парикмахера."},{"tag":"🎻 Из картины — в музыку","q":"Может ли картина породить музыку?","a":"Может. Посмотрев на картину, композитор Пол Зеттер написал менуэт, посвящённый маленькой Тхюи, а в {2024 году|две тысячи двадцать четвёртом году} передал права на это произведение музею."}]},"trong-dong-ngoc-lu":{"title":"Бронзовый барабан Нгоклу","artist":"Носители донгшонской культуры","date":"Около 2000–2500 лет назад (III–II века до н. э.)","medium":"Бронза","where":"Национальный исторический музей, ул. Чангтьен, 1, Ханой","place":{"name":"Национальный исторический музей","prov":"Ханой"},"tags":["Донгшон","бронзовый барабан","национальное сокровище"],"hook":"Этот барабан случайно выкопали, когда насыпали дамбу, а теперь он открывает самый первый список национальных сокровищ Вьетнама. На его поверхности — целый мир древних предков вьетнамцев, если смотреть очень медленно.","intro":"Бронзовый барабан Нгоклу, культура Донгшон, ему примерно от двух до двух с половиной тысяч лет. Рисунок перед вами воспроизводит орнамент на ударной поверхности донгшонского барабана.","openers":["Почему люди, олени и птицы на этом барабане движутся против часовой стрелки?","В самом центре этого барабана есть деталь — число, у которого до сих пор нет общепринятой разгадки.","Найдите на этом барабане целый ряд барабанов, по которым бьют длинными пестами."],"trendLine":"Теперь я понимаю, почему на один бронзовый барабан можно смотреть часами…","end":"Один барабан, а в нём и солнце, и урожай, и праздники, и лодки древних вьетов. Теперь вы понимаете, почему барабан Нгоклу — национальное сокровище.","img":[{"by":"Рисунок-реконструкция орнамента донгшонского барабана: Tom Mai","lic":"Общественное достояние"},{"by":"Фото: VuThiAnh · Национальный исторический музей","lic":"Общественное достояние"}],"steps":[{"tag":"🥁 Нашли, насыпая дамбу","q":"Как выглядит настоящий барабан?","a":"Высота — шестьдесят три сантиметра, ударная поверхность — почти восемьдесят в поперечнике, и весь он покрыт серо-зелёной патиной. Около {1893 года|тысяча восемьсот девяносто третьего года} крестьяне, насыпая дамбу, выкопали его и унесли в общинный дом деревни Нгоклу, чтобы ему поклоняться, а в {1903 году|тысяча девятьсот третьем году} барабан перевезли в Ханой.","s":"Около {1893 года|тысяча восемьсот девяносто третьего года} крестьяне, насыпая дамбу, выкопали его и стали почитать в общинном доме деревни Нгоклу."},{"tag":"☀️ Солнце с 14 лучами","q":"Сколько лучей у звезды в центре барабана?","a":"На барабане Нгоклу их четырнадцать. Большинство исследователей видят в звезде солнце, связанное с культом солнца у древних рисоводов. А почему лучей именно четырнадцать, до сих пор никто объяснить не смог.","s":"Четырнадцать: это солнце древних рисоводов. Почему именно четырнадцать — до сих пор никто не объяснил."},{"tag":"🦚 Павлиньи перья","q":"Что изображено между лучами звезды?","a":"Треугольный узор, похожий на павлиньи перья. От центра барабана расходятся концентрические пояса орнамента; на барабане Нгоклу их шестнадцать."},{"tag":"🪶 Люди-птицы","q":"Что делают люди в головных уборах из перьев?","a":"Они наряжены птицами: одни держат копья, другие играют на кхене — бамбуковом губном органе. Археологи сходятся в том, что это обряд с музыкой. Одни считают его праздником моления об урожае, другие — погребальным обрядом.","s":"Обряд с музыкой: люди в птичьих нарядах, с копьями и кхенами. Праздник урожая это или похороны — спорят до сих пор."},{"tag":"🥁 Барабаны на барабане","q":"Видите барабаны, нарисованные прямо на барабане?","a":"Целый ряд барабанов, и люди бьют по ним длинными пестами. Это прямое доказательство: бронзовые барабаны были музыкальными инструментами общинных обрядов."},{"tag":"🛖 Дом-лодка на сваях","q":"О чём говорит этот дом с крышей, изогнутой, как лодка?","a":"Это дом на сваях с изогнутой крышей в форме лодки, на фронтонах — птичьи головы. Есть мнение, что это обрядовый дом лаквьетов и далёкий прообраз крыши деревенского общинного дома."},{"tag":"🌾 Толкут рис","q":"Что делают эти двое с пестами?","a":"Толкут рис. К пестам прикреплены перья, поэтому многие считают, что это может быть частью обряда урожая у земледельцев, выращивающих заливной рис."},{"tag":"🦌 Олени","q":"Какие животные во внешнем поясе?","a":"Стада оленей и стаи летящих птиц — и все они обращены в одну сторону."},{"tag":"🐦 Птицы лак?","q":"Что за длинноклювые птицы в самом внешнем поясе?","a":"Их принято называть птицами лак, но это лишь условное название. Одни считают их аистами, цаплями или журавлями, другие — бакланами. На барабане Нгоклу их тридцать шесть: восемнадцать летят, восемнадцать стоят.","s":"Их принято называть птицами лак, но что это за птицы на самом деле, до сих пор спорят. На барабане Нгоклу их тридцать шесть."},{"tag":"↺ Против часовой стрелки","q":"Вы заметили, что всё движется в одну сторону?","a":"Люди, олени и птицы движутся вокруг звезды против часовой стрелки. Почему — общепринятого ответа до сих пор нет, есть только гипотезы, например о связи с движением тени от солнца."},{"tag":"🚣 Шесть лодок","q":"А что изображено на боках барабана?","a":"Шесть лодок, а в них люди в уборах из перьев, воины с копьями, кормчие. Боевые это ладьи, гоночные или ладьи, что увозят души умерших? Исследователи спорят до сих пор."}]},"quan-am-but-thap":{"title":"Тысячеглазая и тысячерукая Гуаньинь из пагоды Буттхап","artist":"Мастер по фамилии Чыонг","date":"1656 (осень года Бинь Тхан)","medium":"Дерево, красный лак, позолота","where":"Пагода Буттхап (Ниньфук), провинция Бакнинь","place":{"name":"Пагода Буттхап","prov":"Бакнинь"},"tags":["буддийская скульптура","эпоха Ле","национальное сокровище"],"hook":"Сколько рук у этой статуи? Спросите десятерых — и, возможно, услышите десять разных чисел.","intro":"Тысячеглазая и тысячерукая Гуаньинь, бодхисаттва сострадания, из пагоды Буттхап, Бакнинь: дерево, красный лак и позолота, {1656 год|тысяча шестьсот пятьдесят шестой год}.","openers":["Почему в каждой маленькой ладони этой статуи есть глаз?","На этой статуе есть редкая деталь: она сообщает год, когда её вырезали, и даже того, кто её вырезал.","Остановитесь и посмотрите на руки, сложенные у груди: ладони совсем не прижаты друг к другу."],"trendLine":"Теперь я понимаю, почему перед одной статуей можно стоять часами…","end":"Почти тысяча рук, и на каждой ладони — глаз: урок сострадания, которое умеет и видеть, и действовать. Теперь вы понимаете, почему перед этой статуей можно стоять часами.","img":[{"by":"Фото: Benjamin Smith (CC BY-SA 4.0)","lic":"CC BY-SA 4.0"},{"by":"Фото: Khangoii (CC BY-SA 4.0)","lic":"CC BY-SA 4.0"},{"by":"Фото: Khangoii (CC BY-SA 4.0)","lic":"CC BY-SA 4.0"}],"steps":[{"tag":"📏 3,7 метра","q":"Какой высоты эта статуя?","a":"Почти четыре метра, если считать с постаментом. Статую вырезали в {1656 году|тысяча шестьсот пятьдесят шестом году}, в эпоху восстановленной династии Ле, и она вошла в самый первый список национальных сокровищ в {2012 году|две тысячи двенадцатом году}."},{"tag":"🖐️ Почти тысяча рук","q":"Сколько у неё рук?","a":"Большинство источников насчитывают сорок две большие руки и ореол почти из тысячи маленьких, уложенных в несколько рядов. Каждая книга считает по-своему: девятьсот пятьдесят две, девятьсот пятьдесят восемь… Ведь тысяча здесь — не счёт, а символ полноты и совершенства.","s":"Около сорока двух больших рук и почти тысяча маленьких; в каждой книге своё число, ведь тысяча здесь — символ полноты и совершенства."},{"tag":"👁️ Глаз на ладони","q":"Вы заметили, что в каждой маленькой ладони есть глаз?","a":"Глаз — это знание, рука — действие. Только зная, действуешь правильно, и только действуя, познаёшь глубже. Тысяча глаз и тысяча рук — это сострадание, которое видит всё насквозь и действует, чтобы спасать живых существ."},{"tag":"✖️ 40 × 25 = 1000","q":"Почему сорок две большие руки считаются за тысячу?","a":"Таков канон тысячеруких статуй: если не считать двух сложенных ладоней, каждая из оставшихся сорока рук спасает живых существ в двадцати пяти мирах. Сорок умножить на двадцать пять — ровно тысяча."},{"tag":"🙂 Одиннадцать ликов","q":"Почему у статуи целых одиннадцать ликов?","a":"Лики расположены в несколько ярусов, у каждого своё выражение: они означают, что Гуаньинь является на помощь в любых обстоятельствах. Тибетская легенда рассказывает, что, когда обет спасти всех живых существ пошатнулся, тело Гуаньинь разлетелось на куски, и Будда Амитабха собрал его заново — с одиннадцатью ликами и тысячей рук.","s":"У каждого лика своё выражение: Гуаньинь является в любых обстоятельствах. По тибетской легенде, тело Гуаньинь однажды разлетелось на куски, и Будда Амитабха собрал его заново — с одиннадцатью ликами."},{"tag":"🧘 Амитабха","q":"Кто сидит на самом верху?","a":"Маленькая статуя Будды Амитабхи — её поместили на вершину в знак почитания Будды."},{"tag":"🙏 Ладони с пустотой","q":"Почему руки, сложенные у груди, не прижаты друг к другу?","a":"Ладони не соприкасаются, между ними остаётся пустое пространство. Один исследователь называет этот жест «хы там хьеп тьыонг» — «сложенные ладони с пустотой внутри» — и связывает его с тибетской скульптурой, где в ладонях иногда держат драгоценную жемчужину, символ бодхичитты — стремления к просветлению."},{"tag":"✨ Лак и позолота","q":"Какое выражение у главного лика?","a":"Кроткое, взгляд опущен. Красный лак и позолота, нанесённые в традиционной вьетнамской лаковой технике, делают лицо будто светящимся в полумраке главного зала."},{"tag":"🐉 Дракон и лотосовый трон","q":"Что за существо под лотосовым троном?","a":"По некоторым данным, это Царь драконов, который несёт на голове лотосовый трон, — страж буддийского учения. Лотосовый трон символизирует чистоту, что поднимается из грязи."},{"tag":"✍️ Надпись 1656 года","q":"Где эта статуя подписана?","a":"На статуе есть надпись: сделана осенью года Бинь Тхан, то есть в {1656 году|тысяча шестьсот пятьдесят шестом году}, а рядом — имя резчика; более поздние исследования считают, что это мастер по фамилии Чыонг. Старинная статуя, на которой указаны и год, и мастер, — большая редкость."}]},"chua-mot-cot":{"title":"Пагода на одном столбе","artist":"Построена при императоре Ли Тхай Тонге; нынешнее здание восстановлено под руководством архитектора Нгуен Ба Ланга (1955)","date":"1049 (восстановлена в 1955 году)","medium":"Дерево, камень, черепица","where":"Улица Пагоды на одном столбе, район Бадинь, Ханой","place":{"name":"Пагода на одном столбе","prov":"Ханой"},"tags":["династия Ли","пагода","Ханой"],"hook":"Пагода, которая стоит ровно на одном столбе. Её история началась со сна, а однажды её разрушили всего за одну ночь.","intro":"Пагода на одном столбе в Ханое, её книжное название — Зьенхыу. Первая пагода на этом месте была построена в {1049 году|тысяча сорок девятом году}, при императоре Ли Тхай Тонге.","openers":["Знаете ли вы, что у Пагоды на одном столбе есть книжное название, которое значит «долгое благословение»?","В истории этой пагоды есть деталь: огромный колокол когда-то лежал в поле, и там поселились черепахи.","Найдите на крыше пагоды двух драконов, обращённых к луне, и четыре драконьи головы на углах."],"trendLine":"Теперь я понимаю, почему на одну маленькую пагоду можно смотреть часами…","end":"Сон, столб и лотос посреди пруда. Теперь вы понимаете, почему эта маленькая пагода почти тысячу лет живёт в самом сердце ханойцев.","img":[{"by":"Фото: Daderot (CC0)","lic":"CC0"},{"by":"Фото: Firmin-André Salles, 1896","lic":"Общественное достояние"}],"steps":[{"tag":"🌙 Сон 1049 года","q":"Почему пагода стоит на одном столбе?","a":"Согласно «Полному собранию исторических записок Дайвьета», в {1049 году|тысяча сорок девятом году} императору Ли Тхай Тонгу приснилась Гуаньинь на лотосовом троне: она взяла его за руку и возвела на помост. Придворные сочли сон дурным знаком. Монах Тхьен Туэ посоветовал императору поставить посреди земли каменный столб и водрузить на него лотосовый трон Гуаньинь, как во сне.","s":"Императору Ли Тхай Тонгу приснилась Гуаньинь на лотосовом троне, и монах Тхьен Туэ посоветовал поставить каменный столб, а на него — лотосовый трон, как во сне."},{"tag":"🪷 Зьенхыу","q":"Как на самом деле называется пагода?","a":"Зьенхыу, то есть «долгое благословение»: когда пагоду построили, монахи обходили её по кругу, читая сутры и молясь о долголетии императора. А квадратный павильон на столбе называют Льенхоадай — «Лотосовый трон»."},{"tag":"🏛️ Один столб","q":"Насколько велик этот столб?","a":"Около метра двадцати в диаметре и примерно четыре метра высотой над землёй. Столб — это стебель лотоса, который поднимается из пруда."},{"tag":"🌿 Чашечка цветка","q":"Зачем под полом павильона косые деревянные подпорки?","a":"Они держат павильон и расходятся веером, как чашелистики, на которых покоится цветок лотоса."},{"tag":"🐉 Драконы и луна","q":"Что на крыше пагоды?","a":"Четыре круто загнутых угла крыши украшены головами драконов, а на коньке — два дракона, обращённые к луне."},{"tag":"◻️ Пруд Линьтьеу","q":"Почему пруд квадратный?","a":"Пруд Линьтьеу квадратный, каждая сторона — около шестнадцати метров. Есть прочтение, что квадратный пруд символизирует землю; но это лишь одна из трактовок. Смысл привычнее: чистый лотос, что поднимается из грязи."},{"tag":"🗺️ Ансамбль эпохи Ли","q":"При династии Ли пагода была такой же маленькой, как сейчас?","a":"Нет. В {1105 году|тысяча сто пятом году} император Ли Нян Тонг расширил её: выкопали пруд Линьтьеу, добавили пруд Битьчи, галереи, мосты и башню. Некоторые исследователи видят во всём этом ансамбле мандалу — буддийскую модель вселенной."},{"tag":"📷 1896 год","q":"Что особенного в этой фотографии {1896 года|тысяча восемьсот девяносто шестого года}?","a":"Это Пагода на одном столбе на снимке {1896 года|тысяча восемьсот девяносто шестого года}. Пагода, которую мы видим сегодня, — уже не та постройка."},{"tag":"💥 1954 год","q":"Что произошло одной сентябрьской ночью {1954 года|тысяча девятьсот пятьдесят четвёртого года}?","a":"Прямо перед уходом французских войск из Ханоя пагоду заминировали, и взрыв обрушил павильон. В {1955 году|тысяча девятьсот пятьдесят пятом году} архитектор Нгуен Ба Ланг руководил её восстановлением по образцу эпохи Нгуен. Сегодняшняя пагода — это та самая реконструкция."},{"tag":"🐢 Колокол Куидьен","q":"Почему колокол пагоды оказался в поле, где поселились черепахи?","a":"В {1080 году|тысяча восьмидесятом году}, при династии Ли, для пагоды отлили колокол Зактхе. Он был так тяжёл, что повесить его не смогли и оставили в поле; там поселились черепахи, и колокол прозвали Куидьен — «Черепашье поле». В {1426 году|тысяча четыреста двадцать шестом году} минские войска разбили колокол и пустили бронзу на оружие.","card":{"big":"🔔","sub":"Колокол Куидьен"}}]},"tien-quan-ca":{"title":"Марш армии","artist":"Ван Као (1923–1995)","date":"Конец 1944 года","medium":"Марш","where":"Написан в мансарде дома № 45 по улице Нгуен Тхыонг Хьен, Ханой","place":{"name":"Улица Нгуен Тхыонг Хьен (мансарда, где была написана песня)","prov":"Ханой"},"tags":["гимн Вьетнама","марш","Августовская революция"],"hook":"Песню, под которую вся страна встаёт навытяжку при подъёме флага, написал в тесной мансарде, посреди голода {1944 года|тысяча девятьсот сорок четвёртого года}, двадцатиоднолетний парень, ни разу не державший в руках оружия.","intro":"«Тьен куан ка», или «Марш армии», композитора Ван Као. В этом видео мы не цитируем слова песни, а рассказываем историю, которая стоит за ней.","openers":["Знаете ли вы, что гимн Вьетнама изначально вовсе не писали как гимн?","Деталь из гончарной деревни Батчанг: первый оттиск этой песни правили лимонным соком.","Когда в следующий раз услышите гимн Вьетнама, обратите внимание на первую ноту: когда-то её укоротили, чтобы песня звучала бодрее."],"trendLine":"Теперь я понимаю, почему у миллионов людей наворачиваются слёзы, когда они вместе поют одну песню…","end":"Короткий, как сигнал горна, марш, рождённый среди голода и холода и написанный зеркально на камне для печати. Теперь вы понимаете, почему всякий раз, когда он звучит, у людей наворачиваются слёзы.","img":[{"by":"Фото: rusticus80 (CC BY-SA 2.0)","lic":"CC BY-SA 2.0"},{"by":"Фото: P. Hughes (CC BY 4.0)","lic":"CC BY 4.0"},{"by":"Фото: Bùi Thụy Đào Nguyên (CC BY-SA 4.0)","lic":"CC BY-SA 4.0"},{"by":"Фото: Liftold (CC BY-SA 3.0)","lic":"CC BY-SA 3.0"},{"by":"Фото: Greenknight dv (CC BY-SA 4.0)","lic":"CC BY-SA 4.0"}],"steps":[{"tag":"🕯️ Посреди голода","q":"В каких условиях родилась эта песня?","a":"В конце {1944 года|тысяча девятьсот сорок четвёртого года} голод охватил весь Север Вьетнама. Двадцатиоднолетний Ван Као бедствовал, и бывали ночи, когда он жёг рукописи, чтобы согреться. Он рассказывал, что шёл по улицам, где лежали умершие от голода, и той ночью записал первые ноты.","s":"В конце {1944 года|тысяча девятьсот сорок четвёртого года}, посреди голода: двадцатиоднолетний парень жёг рукописи, чтобы согреться, и записал первые ноты.","card":{"big":"1944","sub":"Мансарда в доме № 45 на улице Нгуен Тхыонг Хьен, Ханой"}},{"tag":"🎺 Как сигнал горна","q":"Песню писали, чтобы она стала гимном?","a":"Нет. Это было первое задание, которое дал ему один из активистов Вьетминя: написать песню для курсов военной подготовки. Ван Као ни разу не бывал в партизанском районе, поэтому писал так, чтобы солдаты могли сразу её запеть, — коротко, как сигнал горна.","card":{"big":"🎺","sub":"Песня для курсов военной подготовки"}},{"tag":"🍋 Зеркально на камне","q":"Где появился первый оттиск песни?","a":"В гончарной деревне Батчанг, в {ноябре 1944 года|ноябре тысяча девятьсот сорок четвёртого года}, в подпольной газете «Доклап» — «Независимость». Ван Као сам написал песню зеркально на камне для литографии, а вместо кислоты правил оттиск лимонным соком. Этот камень спрятали на дне деревенского пруда, и подняли его только в {1984 году|тысяча девятьсот восемьдесят четвёртом году}.","s":"В гончарной деревне Батчанг: Ван Као написал песню зеркально на литографском камне и вместо кислоты использовал лимонный сок."},{"tag":"🏯 Танчао, август 1945","q":"Когда песня стала гимном?","a":"В середине {августа 1945 года|августа тысяча девятьсот сорок пятого года} в Танчао Хо Ши Мин выбрал «Марш армии», потому что песня короткая, сильная и легко поётся. В {1946 году|тысяча девятьсот сорок шестом году} Национальное собрание первого созыва официально её утвердило, и это закрепила первая Конституция."},{"tag":"🌳 Баньян в Танчао","q":"Где солдаты впервые спели эту песню?","a":"По рассказам семьи композитора, бойцы Армии освобождения пели «Марш армии» на церемонии выступления в поход под баньяном в Танчао."},{"tag":"🏛️ Опера Ханоя, 17.08.1945","q":"Почему с этой песней связан Ханойский оперный театр?","a":"{17 августа 1945 года|Семнадцатого августа тысяча девятьсот сорок пятого года} митинг у Оперного театра вдруг принял совсем другой оборот: с балкона спустили красный флаг с жёлтой звездой, и тысячи людей запели хором. Больной Ван Као всё-таки пришёл туда — и расплакался."},{"tag":"🎼 Две ноты","q":"А вы знаете, что первую ноту когда-то исправили?","a":"Ещё до {2 сентября 1945 года|второго сентября тысяча девятьсот сорок пятого года} дирижёр Динь Нгок Льен и Ван Као договорились изменить две ноты и укоротить первую, чтобы песня звучала бодрее. Сегодня поют именно этот исправленный вариант.","card":{"big":"♪","sub":"Первую ноту укоротили"}},{"tag":"🏁 Почти 1500 заявок","q":"Почему поют только первый куплет?","a":"В «Марше армии» два куплета, но с {1955 года|тысяча девятьсот пятьдесят пятого года} официально исполняется только первый. В {1981 году|тысяча девятьсот восемьдесят первом году} на конкурс нового гимна прислали почти полторы тысячи песен, но в итоге Национальное собрание оставило «Марш армии»."},{"tag":"🤝 Дар государству, 2016","q":"Кому принадлежит гимн?","a":"{15 июля 2016 года|Пятнадцатого июля две тысячи шестнадцатого года} семья композитора Ван Као официально передала песню в дар государству. Как говорил сам автор, песня давно принадлежит не ему одному, а всем вьетнамцам.","card":{"big":"2016","sub":"Песня принадлежит всем"}}]},"quan-ho-nguoi-oi-nguoi-o-dung-ve":{"title":"Куанхо: «Друг мой, останься, не уходи»","artist":"Народная песня куанхо (популярная версия в редакции композитора Суан Ты, 1958)","date":"Многовековая традиция; редакция 1958 года","medium":"Народная песня, пение-диалог без аккомпанемента","where":"49 исконных деревень куанхо по обоим берегам реки Кау, Бакнинь","place":{"name":"Деревня Зьем (Вьемса) — место почитания Вуа Ба, прародительницы куанхо","prov":"Бакнинь"},"tags":["куанхо","ЮНЕСКО","народная песня"],"hook":"Они поют друг другу всю ночь, зовут друг друга «братец» и «сестрица» и привязаны друг к другу всей душой. Но есть деревенский обычай: друзьям по куанхо нельзя жениться.","intro":"Народные песни куанхо из Бакниня, в {2009 году|две тысячи девятом году} внесённые в список ЮНЕСКО. Слова песен мы не цитируем — только история, что стоит за ними.","openers":["Знаете ли вы, что эту известную прощальную песню куанхо в {1958 году|тысяча девятьсот пятьдесят восьмом году} переработал композитор?","Деталь о шляпе нон куай тхао: в старину исполнители куанхо иногда закрывали ею лицо.","Когда в следующий раз услышите куанхо, прислушайтесь к приёму «най»: звук очень быстро перехватывают в горле, и он вырывается наружу."],"trendLine":"Теперь я понимаю, почему куанхо можно слушать всю ночь напролёт…","end":"Ночь пения без аккомпанемента, близость, которой не суждено стать браком, и просьба остаться, когда занимается рассвет. Теперь вы понимаете, почему куанхо можно слушать всю жизнь.","img":[{"by":"Фото: Chrisvomberg (CC BY-SA 3.0)","lic":"CC BY-SA 3.0"},{"by":"Фото: Viethavvh (CC BY-SA 3.0)","lic":"CC BY-SA 3.0"},{"by":"Фото: Vanminhhanoi (CC BY-SA 3.0)","lic":"CC BY-SA 3.0"}],"steps":[{"tag":"🤝 Дружба куанхо","q":"Кто такие льен ань и льен ти?","a":"Так называют певцов и певиц куанхо. Мужская группа одной деревни заводит дружбу с женской группой другой, и петь вместе могут только те, кто подружился. Поют в диалоге: одна сторона заводит напев, другая отвечает похожей мелодией, но на другие слова."},{"tag":"🏘️ 49 исконных деревень","q":"Откуда взялись сорок девять исконных деревень куанхо?","a":"Сорок девять деревень лежат по обоим берегам реки Кау. Легенда рассказывает о Вуа Ба — царице, дочери короля Хунга, которая научила жителей деревни Зьем сажать рис, ткать шёлк и петь. По другой версии, она назвала братьями и сёстрами сорок девять человек, и те разошлись по округе учить людей куанхо.","card":{"big":"49","sub":"исконных деревень куанхо по берегам реки Кау"}},{"tag":"💔 Запрет на брак","q":"Почему друзьям по куанхо нельзя жениться?","a":"Таков деревенский обычай: кое-где его даже вписывали в деревенский устав, о нём упоминает и ЮНЕСКО, хотя находились пары, которые его нарушали. Один пожилой исполнитель куанхо считает, что именно этот запрет рождает лёгкую печаль в напевах куанхо.","card":{"big":"💔","sub":"Любить, но не жениться"}},{"tag":"🌙 Пение до утра","q":"Сколько длится одна ночь пения куанхо?","a":"С сумерек до рассвета — около десяти часов, без усилителей и без аккомпанемента. В такой ночи обязательно три части: сначала строгие старинные напевы по канону, затем песни повольнее и, наконец, прощание с друзьями, когда уже светает.","card":{"big":"19:00 → 5:00","sub":"Одна ночь пения"}},{"tag":"🎙️ Ванг, зен, нен, най","q":"Что значат ванг, зен, нен и най?","a":"Ванг — это голос, который летит далеко. Зен — ровная вибрация, без обрыва дыхания. Най — звук, который очень быстро перехватывают в горле, а потом он вырывается наружу. А о том, что такое нен, спорят до сих пор.","card":{"big":"Ванг · Зен · Нен · Най","sub":"Четыре слова о голосе куанхо"}},{"tag":"👒 Шляпа нон куай тхао","q":"Зачем нужна эта шляпа почти восемьдесят сантиметров в поперечнике?","a":"Это нон куай тхао — шляпа с завязками из шёлковых нитей. В старину те, кто пел в паре, иногда прикрывали ею лицо во время пения."},{"tag":"👘 Платье ао мо ба","q":"Во что одеты певицы?","a":"В ао мо ба — три платья, надетые одно поверх другого, персиковый нагрудник, платок «вороний клюв» и пояс, завязанный спереди в форме лепестков."},{"tag":"🎩 Халат ао тхе и тюрбан","q":"А певцы?","a":"Чёрный халат из тонкого шёлка поверх аозая, тюрбан, зонт из блестящего шёлка — и очень скромное обращение: себя называют «младшими», а друзей — «старшим братом» и «старшей сестрой», никто не ставит себя выше другого."},{"tag":"🛶 Праздничное пение","q":"Пение на лодках — это старинное куанхо?","a":"Не совсем. Пение на лодках — в основном праздничное развлечение. Старинная традиция — это ночное пение: ночью, в доме, между группами куанхо, которые подружились."},{"tag":"🎶 Суан Ты, 1958","q":"Правда ли, что песня «Друг мой, останься, не уходи» — старинная?","a":"Не совсем. Популярную сегодня версию в {1958 году|тысяча девятьсот пятьдесят восьмом году} сделал композитор Суан Ты на основе старинной песни куанхо. Он сократил её, оставив только расставание, напутствия и тоску, и поднял припев выше, чтобы мольба остаться звучала пронзительнее.","card":{"big":"1958","sub":"Редакция композитора Суан Ты"}},{"tag":"🌅 Прощание на рассвете","q":"Почему прощальная песня такая грустная?","a":"Потому что она звучит после долгой ночи совместного пения, когда уже светает: хозяева уговаривают гостей остаться, договариваются о новой встрече — и знают, что по обычаю эта дружба никогда не станет браком."}]}}};
